import React, { useEffect, useRef } from 'react';

// Native SVG Bezier Chart - Area Chart Linear
// Desktop: var(--chart-1), Mobile: var(--chart-2)
interface AreaLinearChartProps {
  title?: string;
  description?: string;
  className?: string;
}

export function AreaLinearChart({
  title = "Area Chart Linear",
  description = "Linear point-to-point area chart with straight segment boundaries.",
  className = ""
}: AreaLinearChartProps) {
  const chartRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = chartRef.current;
    if (!container) return;
    const svg = container.querySelector('svg');
    const tooltip = container.querySelector<HTMLElement>('[data-chart-tooltip]');
    const crosshair = container.querySelector('[data-crosshair]');
    const dotDesktop = container.querySelector('[data-crosshair-desktop]');
    const dotMobile = container.querySelector('[data-crosshair-mobile]');
    if (!svg) return;

    const ro = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const { width, height } = entry.contentRect;
        if (width > 0 && height > 0) {
          svg.setAttribute('viewBox', `0 0 ${Math.round(width)} ${Math.round(height)}`);
        }
      }
    });
    ro.observe(container);

    const dataPoints = [
      { month: 'Jan', x: 60, desktop: 186, mobile: 80, yD: 140, yM: 180 },
      { month: 'Feb', x: 160, desktop: 305, mobile: 200, yD: 100, yM: 155 },
      { month: 'Mar', x: 260, desktop: 237, mobile: 120, yD: 85, yM: 140 },
      { month: 'Apr', x: 360, desktop: 73, mobile: 190, yD: 125, yM: 130 },
      { month: 'May', x: 460, desktop: 209, mobile: 130, yD: 75, yM: 110 },
      { month: 'Jun', x: 560, desktop: 214, mobile: 140, yD: 35, yM: 75 }
    ];

    const onMouseMove = (e: MouseEvent) => {
      const rect = svg.getBoundingClientRect();
      const mouseX = ((e.clientX - rect.left) / rect.width) * 600;
      let closest = dataPoints[0];
      let minDist = Infinity;
      for (const pt of dataPoints) {
        const dist = Math.abs(pt.x - mouseX);
        if (dist < minDist) {
          minDist = dist;
          closest = pt;
        }
      }
      if (crosshair) {
        crosshair.setAttribute('x1', String(closest.x));
        crosshair.setAttribute('x2', String(closest.x));
        crosshair.classList.remove('opacity-0');
      }
      if (dotDesktop) {
        dotDesktop.setAttribute('cx', String(closest.x));
        dotDesktop.setAttribute('cy', String(closest.yD));
        dotDesktop.classList.remove('opacity-0');
      }
      if (dotMobile) {
        dotMobile.setAttribute('cx', String(closest.x));
        dotMobile.setAttribute('cy', String(closest.yM));
        dotMobile.classList.remove('opacity-0');
      }
      if (tooltip) {
        tooltip.classList.remove('opacity-0');
        tooltip.style.left = `${(closest.x / 600) * 100}%`;
        tooltip.style.transform = 'translateX(-50%)';
      }
    };

    const onMouseLeave = () => {
      if (crosshair) crosshair.classList.add('opacity-0');
      if (dotDesktop) dotDesktop.classList.add('opacity-0');
      if (dotMobile) dotMobile.classList.add('opacity-0');
      if (tooltip) tooltip.classList.add('opacity-0');
    };

    svg.addEventListener('mousemove', onMouseMove);
    svg.addEventListener('mouseleave', onMouseLeave);

    return () => {
      ro.disconnect();
      svg.removeEventListener('mousemove', onMouseMove);
      svg.removeEventListener('mouseleave', onMouseLeave);
    };
  }, []);

  return (
    <div id="area-linear" ref={chartRef} className={`w-full ${className}`}>
      <div className="chart-container card p-6 flex flex-col gap-4 w-full bg-background/95 backdrop-blur-sm" role="img" aria-label="Area Chart Linear - Linear point-to-point area chart with straight segment boundaries." id="area-linear">
  <div className="border-b border-border pb-3 flex items-center justify-between">
    <div>
      <h3 className="text-base font-semibold text-foreground">Area Chart Linear</h3>
      <p className="text-sm text-muted-foreground">Linear point-to-point area chart with straight segment boundaries.</p>
    </div>
    <div className="flex items-center gap-4 text-xs">
      <div className="flex items-center gap-1.5">
        <span className="size-2.5 rounded-full" style={{ backgroundColor: "var(--chart-1)" }}></span>
        <span className="text-muted-foreground">Desktop</span>
      </div>
      <div className="flex items-center gap-1.5">
        <span className="size-2.5 rounded-full" style={{ backgroundColor: "var(--chart-2)" }}></span>
        <span className="text-muted-foreground">Mobile</span>
      </div>
    </div>
  </div>
  <div className="w-full aspect-[4/3] md:aspect-[16/9] lg:aspect-[2/1] min-h-[240px] relative flex items-center justify-center overflow-hidden" data-chart-viewport>
    <svg className="w-full h-full" viewBox="0 0 600 240" preserveAspectRatio="none" role="img" aria-label="Area Chart">
        <defs>
          <linearGradient id="fillDesktop" x1="0" y1="0" x2="0" y2="1">
            <stop offset="5%" stopColor="var(--chart-1)" stopOpacity="0.8"/>
            <stop offset="95%" stopColor="var(--chart-1)" stopOpacity="0.1"/>
