        <circle data-crosshair-mobile cx="260" cy="140" r="4" fill="var(--chart-2)" className="opacity-0 transition-opacity"/>
      </svg>
    <div className="rounded-lg border border-border bg-background/95 p-2.5 text-xs shadow-xl backdrop-blur-sm flex flex-col gap-1 z-10" data-chart-tooltip>
    <span className="font-semibold text-muted-foreground">Series Overview</span>
