    <div id="area-gradient" ref={chartRef} className={`w-full ${className}`}>
      <div className="chart-container card p-6 flex flex-col gap-4 w-full bg-background/95 backdrop-blur-sm" role="img" aria-label="Area Chart Gradient - Area chart styled with vertical fade gradient." id="area-gradient">
  <div className="border-b border-border pb-3 flex items-center justify-between">
