    </div>
    <div className="flex items-center gap-4 text-xs">
      <div className="flex items-center gap-1.5">
        <span className="size-2.5 rounded-full" style={{ backgroundColor: "var(--chart-1)" }}></span>
        <span className="text-muted-foreground">Desktop</span>
      </div>
      <div className="flex items-center gap-1.5">
        <span className="size-2.5 rounded-full" style={{ backgroundColor: "var(--chart-2)" }}></span>
        <span className="text-muted-foreground">Mobile</span>
      </div>
    </div>
  </div>
  <div className="w-full aspect-[4/3] md:aspect-[16/9] lg:aspect-[2/1] min-h-[240px] relative flex items-center justify-center overflow-hidden" data-chart-viewport>
    <svg className="w-full h-full" viewBox="0 0 600 240" preserveAspectRatio="none" role="img" aria-label="Area Chart">
