import React, { useEffect, useRef } from 'react';

// Native SVG Bezier Chart - Bar Chart Multiple
// Desktop: var(--chart-1), Mobile: var(--chart-2)
interface BarMultipleChartProps {
  title?: string;
  description?: string;
  className?: string;
}

export function BarMultipleChart({
  title = "Bar Chart Multiple",
  description = "Clustered multi-series bar chart contrasting grouped periods.",
  className = ""
}: BarMultipleChartProps) {
  const chartRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = chartRef.current;
    if (!container) return;
