// Native SVG Bezier Chart - Bar Chart Negative
// Desktop: var(--chart-1), Mobile: var(--chart-2)
interface BarNegativeChartProps {
  title?: string;
  description?: string;
  className?: string;
}

export function BarNegativeChart({
  title = "Bar Chart Negative",
  description = "Diverging bar chart depicting positive gains and negative variances from baseline.",
  className = ""
}: BarNegativeChartProps) {
  const chartRef = useRef<HTMLDivElement>(null);

