// Mount and bind Bar Chart Active State (ApexCharts)
import ApexCharts from 'apexcharts';

const chartOptions = {
  "chart": {
    "type": "bar",
    "height": "100%",
    "toolbar": {
      "show": false
    },
    "fontFamily": "inherit",
    "stacked": false
  },
  "plotOptions": {
    "bar": {
      "horizontal": false,
      "borderRadius": 4,
      "columnWidth": "55%"
    }
  },
  "colors": [
    "var(--chart-1)",
    "var(--chart-2)",
    "var(--chart-3)",
    "var(--chart-4)",
    "var(--chart-5)"
  ],
  "grid": {
    "borderColor": "var(--color-border)",
    "strokeDashArray": 4
  },
  "xaxis": {
    "labels": {
      "style": {
        "colors": "var(--color-muted-foreground)"
      }
    },
    "axisBorder": {
      "color": "var(--color-border)"
    },
    "axisTicks": {
      "color": "var(--color-border)"
    }
  },
  "yaxis": {
    "labels": {
      "style": {
        "colors": "var(--color-muted-foreground)"
      }
    }
  },
  "tooltip": {
    "theme": "dark"
  }
};
const container = document.getElementById("bar-active");
if (container) {
  const chartEl = container.querySelector("[data-chart-viewport]") || container;
  const chart = new ApexCharts(chartEl, chartOptions);
  chart.render();
}

