interface LineLinearChartProps {
  title?: string;
  description?: string;
  className?: string;
}

export function LineLinearChart({
  title = "Line Chart Linear",
  description = "Linear line chart with direct straight coordinate segments.",
  className = ""
}: LineLinearChartProps) {
  const chartRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = chartRef.current;
    if (!container) return;
    const svg = container.querySelector('svg');
    const tooltip = container.querySelector<HTMLElement>('[data-chart-tooltip]');
    const crosshair = container.querySelector('[data-crosshair]');
