import React, { useEffect, useRef } from 'react';

// Native SVG Bezier Chart - Line Chart with Dots
// Desktop: var(--chart-1), Mobile: var(--chart-2)
interface LineDotsChartProps {
  title?: string;
  description?: string;
  className?: string;
}

export function LineDotsChart({
  title = "Line Chart with Dots",
  description = "Line chart with distinct point markers at each coordinate.",
  className = ""
}: LineDotsChartProps) {
  const chartRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = chartRef.current;
    if (!container) return;
    const svg = container.querySelector('svg');
    const tooltip = container.querySelector<HTMLElement>('[data-chart-tooltip]');
