// Mount and bind Pie Chart Default (ApexCharts)
import ApexCharts from 'apexcharts';

const chartOptions = {
  "chart": {
    "type": "pie",
    "height": "100%",
    "toolbar": {
      "show": false
    },
    "fontFamily": "inherit"
  },
  "colors": [
    "var(--chart-1)",
    "var(--chart-2)",
    "var(--chart-3)",
    "var(--chart-4)",
    "var(--chart-5)"
  ],
  "stroke": {
    "colors": [
      "var(--color-border)"
    ],
    "width": 1
  },
  "legend": {
    "labels": {
      "colors": "var(--color-muted-foreground)"
    }
  },
  "tooltip": {
    "theme": "dark"
  }
};
const container = document.getElementById("pie-default");
if (container) {
  const chartEl = container.querySelector("[data-chart-viewport]") || container;
  const chart = new ApexCharts(chartEl, chartOptions);
  chart.render();
