import ApexCharts from 'apexcharts';

const chartOptions = {
  "chart": {
    "type": "radar",
    "height": "100%",
    "toolbar": {
      "show": false
    },
    "fontFamily": "inherit"
  },
  "colors": [
    "var(--chart-1)",
    "var(--chart-2)"
  ],
  "stroke": {
    "width": 2
  },
  "fill": {
    "opacity": 0.2
  },
  "markers": {
    "size": 0
  },
  "yaxis": {
    "show": false
  },
  "xaxis": {
    "labels": {
      "style": {
        "colors": [
          "var(--color-muted-foreground)"
        ]
      }
    }
  },
  "tooltip": {
    "theme": "dark"
  }
};
const container = document.getElementById("radar-grid-custom");
if (container) {
  const chartEl = container.querySelector("[data-chart-viewport]") || container;
  const chart = new ApexCharts(chartEl, chartOptions);
  chart.render();
}

