  <div className="w-full aspect-[4/3] md:aspect-[16/9] lg:aspect-[2/1] min-h-[240px] relative flex items-center justify-center overflow-hidden" data-chart-viewport>
    <div className="flex items-center justify-center h-full w-full">
        <div className="relative size-44 flex items-center justify-center">
          <svg className="size-full -rotate-90" viewBox="0 0 100 100" role="img" aria-label="Radial Gauge">
            <circle cx="50" cy="50" r="36" fill="none" stroke="currentColor" strokeOpacity="0.1" strokeWidth="8"/>
            <circle cx="50" cy="50" r="36" fill="none" stroke="var(--chart-1)" strokeWidth="8" strokeDasharray="226" strokeDashoffset="60" strokeLinecap="round"/>
          </svg>
          <div className="absolute flex flex-col items-center">
            <strong className="text-2xl font-bold tabular-nums">72%</strong>
            <span className="text-[10px] text-muted-foreground uppercase">Goal</span>
          </div>
        </div>
      </div>
