            <circle cx="50" cy="50" r="36" fill="none" stroke="currentColor" strokeOpacity="0.1" strokeWidth="8"/>
            <circle cx="50" cy="50" r="36" fill="none" stroke="var(--chart-1)" strokeWidth="8" strokeDasharray="226" strokeDashoffset="60" strokeLinecap="round"/>
          </svg>
          <div className="absolute flex flex-col items-center">
