          </linearGradient>
        </defs>
        <g className="stroke-border/50" strokeWidth="1" strokeDasharray="3 3">
          <line x1="50" y1="30" x2="570" y2="30"/>
          <line x1="50" y1="75" x2="570" y2="75"/>
          <line x1="50" y1="120" x2="570" y2="120"/>
