import React, { useEffect, useRef } from 'react';

// Native SVG Bezier Chart - Tooltip Minimal Value
// Desktop: var(--chart-1), Mobile: var(--chart-2)
interface TooltipNoLabelChartProps {
  title?: string;
  description?: string;
  className?: string;
}

export function TooltipNoLabelChart({
  title = "Tooltip Minimal Value",
  description = "Compact badge tooltip displaying only numeric value.",
  className = ""
