        <path d="M 60,140 C 130,110 170,130 230,85 C 290,40 330,95 390,60 C 450,25 490,55 560,35" fill="none" stroke="var(--chart-1)" strokeWidth="2"/>
        <g className="fill-muted-foreground text-[11px]" textAnchor="middle">
